Calculation.Text:
// Tooltip calculation 
If ( 

//Check to see whether there is a related record.
	IsEmpty(Employees::Name) and IsEmpty ( Assignments::AssetForeignKey ) = 0; 


//Display this message if the related record is missing.
	"Used By: " & Assignments::Name & ¶ & ¶ &

	"The employee ID is displayed in the field because the related employee record has been deleted. The deleted name is stored in the Assignment table." ; 

//Display this message if the related record is found.
	"Used By"

)

